seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

stops = {"TAA","TAG","TGA"}
starts = {"ATG","GTG","TTG"}

def rc(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# find all stop codons in each frame on both strands
for strand, s in [("+", seq), ("-", rc(seq))]:
    L = len(s)
    for frame in range(3):
        stopsites = [i for i in range(frame, L-2, 3) if s[i:i+3] in stops]
        # intervals between stops
        prev = -3
        orfs = []
        for st in stopsites:
            start = st+3
            if st - prev >= 180:  # >=60 aa
                seg = s[prev+3:st]
                first_pos = prev+3
                # find first START within
                atg = None
                for j in range(first_pos, st-2, 3):
                    if s[j:j+3] in starts:
                        atg = j
                        break
                orfs.append((prev+3, st, st-(prev+3), atg))
            prev = st
        if orfs:
            print(f"--- strand {strand} frame {frame} ---")
            for a,b,ln,atg in orfs:
                startcodon = f"start@{atg}({s[atg:atg+3]})" if atg is not None else "no start"
                print(f"  ORF {a}-{b} len {ln}nt ({ln//3}aa) {startcodon}")
