seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

# Exhaustive list of ORFs >= 60 aa (180 nt span) both strands, 1-based coordinates.
code={}; bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"; i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases: code[b1+b2+b3]=aas[i]; i+=1
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
def translate(s): return "".join(code[s[i:i+3]] for i in range(0,len(s)-2,3))
L=len(seq)

rows=[]
for strand in "+-":
    s = seq if strand=="+" else rc(seq)
    for fr in range(3):
        stoppos=[i for i in range(fr, L-2, 3) if s[i:i+3] in ("TAA","TAG","TGA")]
        for si, st in enumerate(stoppos):
            startwin = stoppos[si-1]+3 if si>0 else fr
            if st - startwin >= 180:
                fs=None;  starts_list=[]
                for j in range(startwin, st-2, 3):
                    if s[j:j+3] in ("ATG","GTG","TTG"):
                        starts_list.append(j)
                fs = starts_list[0] if starts_list else startwin
                prot = translate(s[fs:st])[:-1]
                if strand=="+": g1,g2 = fs+1, st+3-1+3-3+3  # compute cleanly below
                if strand=="+":
                    g1, g2 = fs+1, st+3
                else:
                    # rc codon indices fs..st map to genomic L-1-st .. L-1-fs (0-based) => 1-based L-st+1? recompute
                    g1, g2 = L-1-st+1, L-1-fs+1
                starts1 = [ (L-1-j+1) if strand=="-" else j+1 for j in starts_list ]
                rows.append(dict(strand=strand, fr=fr, g1=g1, g2=g2, aa=len(prot),
                                 istops=prot.count("*"), start1=starts1,
                                 hyd=100*sum(1 for a in prot if a in "AILMFWVYC")/len(prot),
                                 prot=prot))
rows.sort(key=lambda r: -(r["g2"]-r["g1"]))
for r in rows:
    print(f"{r['strand']} f{r['fr']} nt {r['g1']}..{r['g2']} ({r['g2']-r['g1']+1}nt) {r['aa']}aa iStops{r['istops']} hyd%{r['hyd']:.0f} starts@{r['start1'][:4]}")
    if r['istops']==0 and 100<=r['aa']<=200:
        print("    ", r['prot'][:75], "...")
import json
open("orfs.json","w").write(json.dumps([{k:v for k,v in r.items() if k!='prot'} for r in rows], indent=1))
"}
